"use client";

import { useEffect, useState } from "react";
import EventRegistrationModal from "@/components/EventRegistrationModal";

interface Event {
    id: string;
    title: string;
    description: string;
    startDate: string;
    endDate?: string;
    location: string;
    imageUrl?: string;
    eventType: string;
    isOpen: boolean;
}
const demoEvents: Event[] = [
    { id: "1", title: "Олон Улсын Зуслангийн Эрдэмтэн Судлаачдын 3-р Хурал", description: "Ази Номхон Далайн орнуудын болон бусад олон улсын судлаачид оролцох.", startDate: "2024-10-15T00:00:00Z", location: "Улаанбаатар хот", eventType: "CONFERENCE", isOpen: true },
    { id: "2", title: "Артек ОУХТ Солилцооны Хөтөлбөр 2024", description: "ОХУ-ын Артек зусланд амрах хүүхдүүдийн бүртгэл.", startDate: "2024-06-01T00:00:00Z", location: "ОХУ, Гурзуф", eventType: "EXCHANGE_PROGRAM", isOpen: true },
    { id: "3", title: "Зуслангийн Удирдлагын Нэгдсэн Сургалт", description: "Зуслангуудын удирдлага, менежерүүдэд зориулсан чадавхжуулах сургалт.", startDate: "2024-05-10T00:00:00Z", location: "Цонжин болдог", eventType: "TRAINING", isOpen: false },
];

import Link from "next/link";

export default function EventsPage() {
    const [events, setEvents] = useState<Event[]>([]);
    const [loading, setLoading] = useState(true);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedEventId, setSelectedEventId] = useState("");
    const [selectedEventTitle, setSelectedEventTitle] = useState("");

    const openModal = (id: string, title: string) => {
        setSelectedEventId(id);
        setSelectedEventTitle(title);
        setIsModalOpen(true);
    };

    useEffect(() => {
        async function fetchEvents() {
            try {
                const response = await fetch("/api/events");
                const data = await response.json();
                if (Array.isArray(data)) {
                    setEvents(data.length > 0 ? data : demoEvents);
                }
            } catch (error) {
                console.error("Failed to load events", error);
            } finally {
                setLoading(false);
            }
        }

        fetchEvents();
    }, []);

    const formatDateRange = (start: string, end?: string) => {
        const options: Intl.DateTimeFormatOptions = { year: 'numeric', month: '2-digit', day: '2-digit' };
        const startDateString = new Date(start).toLocaleDateString('mn-MN', options);
        if (end) {
            const endDateString = new Date(end).toLocaleDateString('mn-MN', options);
            if (startDateString !== endDateString) return `${startDateString} - ${endDateString}`;
        }
        return startDateString;
    };

    const getTypeLabel = (type: string) => {
        switch (type) {
            case 'CONFERENCE': return 'Хурал, зөвлөгөөн';
            case 'EXCHANGE_PROGRAM': return 'Солилцооны хөтөлбөр';
            case 'TRAINING': return 'Сургалт';
            default: return 'Бусад';
        }
    };

    return (
        <div className="container mx-auto px-4 py-12 md:py-24">
            <div className="space-y-4 text-center mb-12">
                <h1 className="text-4xl font-bold tracking-tighter sm:text-5xl text-primary">Арга хэмжээ, Хөтөлбөрүүд</h1>
                <p className="text-lg text-muted-foreground max-w-[700px] mx-auto">
                    Олон улсын болон үндэсний хэмжээний арга хэмжээ, хурал, солилцооны хөтөлбөрийн мэдээлэл.
                </p>
            </div>

            {loading ? (
                <div className="flex justify-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                </div>
            ) : events.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {events.map((event) => (
                        <EventCard 
                            key={event.id} 
                            event={event} 
                            formatDateRange={formatDateRange}
                            getTypeLabel={getTypeLabel}
                            openModal={openModal}
                        />
                    ))}
                </div>
            ) : (
                <div className="text-center py-20 border rounded-lg bg-slate-50">
                    <h3 className="text-lg font-medium text-slate-600">Одоогоор зарлагдсан арга хэмжээ алга байна.</h3>
                </div>
            )}

            {/* Registration Modal */}
            <EventRegistrationModal 
                isOpen={isModalOpen} 
                onClose={() => setIsModalOpen(false)} 
                eventId={selectedEventId}
                eventTitle={selectedEventTitle}
            />
        </div>
    );
}

function EventCard({ event, formatDateRange, getTypeLabel, openModal }: { 
    event: Event; 
    formatDateRange: (start: string, end?: string) => string; 
    getTypeLabel: (type: string) => string;
    openModal: (id: string, title: string) => void;
}) {
    return (
        <div className="rounded-lg border bg-card text-card-foreground shadow-sm flex flex-col overflow-hidden h-full transition-all duration-300 hover:shadow-md">
            {/* Image Placeholder or Actual Image */}
            <div className={`w-full h-48 bg-slate-100 relative ${!event.imageUrl && 'flex items-center justify-center'}`}>
                {event.imageUrl ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={event.imageUrl} alt={event.title} className="w-full h-full object-cover" />
                ) : (
                    <svg className="w-12 h-12 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                )}
            </div>

            <div className="p-6 flex flex-col flex-1">
                <div className="mb-4 flex items-center justify-between">
                    <span className="inline-flex items-center rounded-full bg-blue-100 px-2.5 py-0.5 text-xs font-semibold text-blue-800 dark:bg-blue-900 dark:text-blue-200">
                        {getTypeLabel(event.eventType)}
                    </span>
                    {event.isOpen ? (
                        <span className="inline-flex items-center rounded-full bg-green-100 px-2.5 py-0.5 text-xs font-semibold text-green-800">
                            Бүртгэл нээлттэй
                        </span>
                    ) : (
                        <span className="inline-flex items-center rounded-full bg-red-100 px-2.5 py-0.5 text-xs font-semibold text-red-800">
                            Бүртгэл хаагдсан
                        </span>
                    )}
                </div>
                
                <h3 className="text-xl font-semibold mb-2 line-clamp-2">{event.title}</h3>
                
                <div className="flex-1">
                    <p className="text-sm text-muted-foreground whitespace-pre-wrap line-clamp-3">
                        {event.description}
                    </p>
                    <Link href={`/events/${event.id}`} className="inline-flex items-center text-primary text-sm font-medium mt-3 hover:underline">
                        Дэлгэрэнгүй үзэх
                        <svg className="ml-1 w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" /></svg>
                    </Link>
                </div>
                
                <div className="space-y-2 text-sm border-t pt-4 mt-4">
                    <div className="flex items-center gap-2">
                        <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        <span className="font-medium text-slate-700">{formatDateRange(event.startDate, event.endDate)}</span>
                    </div>
                </div>
                
                <div className="mt-6 flex gap-3">
                    <button
                        disabled={!event.isOpen}
                        onClick={() => openModal(event.id, event.title)}
                        className="flex-1 inline-flex h-10 items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 disabled:opacity-50 disabled:pointer-events-none"
                    >
                        Бүртгүүлэх
                    </button>
                    <Link href={`/events/${event.id}`} className="inline-flex h-10 w-10 items-center justify-center rounded-md border text-slate-500 hover:bg-slate-50 transition-colors">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </Link>
                </div>
            </div>
        </div>
    );
}
